package com.clouddocs.permission;
import com.clouddocs.auth.*;import com.clouddocs.document.*;import com.clouddocs.audit.*;import org.junit.jupiter.api.*;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class SentSharesTest {
 final DocumentPermissionRepository permissions=mock(DocumentPermissionRepository.class);final UserRepository users=mock(UserRepository.class);final DocumentPermissionService service=new DocumentPermissionService(permissions,mock(DocumentRepository.class),users,mock(AuditLogService.class));User actor,target;Document doc;DocumentPermission permission;
 @BeforeEach void setup(){actor=new User();actor.setUsername("actor");ReflectionTestUtils.setField(actor,"id",1L);target=new User();target.setUsername("receiver");target.setFullName("Recipient Name");target.setDepartment("Sales");target.setEmail("receiver@example.com");ReflectionTestUtils.setField(target,"id",2L);doc=new Document();ReflectionTestUtils.setField(doc,"id",7L);doc.setOwnerId(1L);doc.setTitle("Report");doc.setFileName("report.pdf");doc.setFileType("PDF");permission=new DocumentPermission();ReflectionTestUtils.setField(permission,"id",8L);permission.setDocument(doc);permission.setUser(target);permission.setPermission(DocumentPermissionType.VIEW);when(users.findByUsernameIgnoreCase("actor")).thenReturn(Optional.of(actor));when(permissions.findOutgoing(1L,false)).thenReturn(List.of(permission));}
 @Test void ownOutgoingGrantsShowRecipientDepartmentAndCurrentPermission(){var rows=service.listSent("actor");assertEquals(1,rows.size());var row=rows.getFirst();assertEquals("Recipient Name",row.fullName());assertEquals("Sales",row.department());assertEquals("VIEW",row.permission());assertTrue(row.canManage());verify(permissions).findOutgoing(1L,false);verify(permissions,never()).findAll();}
 @Test void foreignOwnersAreNotExposedToOrdinaryUserEvenIfRepositoryReturnsThem(){doc.setOwnerId(3L);assertTrue(service.listSent("actor").isEmpty());}
 @Test void trashKeepsGrantVisibleButDisablesManagementAndPurgedDisappears(){doc.setStatus("TRASHED");assertFalse(service.listSent("actor").getFirst().canManage());doc.setStatus("PURGED");assertTrue(service.listSent("actor").isEmpty());}
 @Test void deletedRecipientsAreNotShown(){target.setStatus("DELETED");assertTrue(service.listSent("actor").isEmpty());}
 @Test void adminUsesAuthorAwareOutgoingQuery(){actor.setRole("ADMIN");when(permissions.findOutgoing(1L,true)).thenReturn(List.of(permission));assertEquals(1,service.listSent("actor").size());verify(permissions).findOutgoing(1L,true);}
 @Test void lockedActorCannotReadGrants(){actor.setStatus("LOCKED");assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.listSent("actor"));verifyNoInteractions(permissions);}
 @Test void endpointIgnoresRequestedAccountAndUsesAuthenticatedIdentity()throws Exception{var mockService=mock(DocumentPermissionService.class);when(mockService.listSent("actor")).thenReturn(List.of());var mvc=MockMvcBuilders.standaloneSetup(new SentSharesController(mockService)).build();mvc.perform(get("/api/shares/sent?userId=99&admin=true").principal(new UsernamePasswordAuthenticationToken("actor",null))).andExpect(status().isOk());verify(mockService).listSent("actor");}
}
